# [doc = " Ethernet II frame (variable parts of a packet)"] # [doc = " "] # [doc = " P is length of data's byte representation"] # [derive (Clone , Copy , Debug)] pub struct EthernetFrame < const P : usize > { # [doc = " Ethernet frame header"] pub header : EthernetHeader , # [doc = " Ethernet payload (likely some kind of IP packet)"] pub data : [u8 ; P] , } impl < const P : usize > EthernetFrame < P > { # [doc = " Generate new, complete frame from components"] pub fn new (header : EthernetHeader , data : [u8 ; P]) -> Self { let enetframe : EthernetFrame < P > = EthernetFrame { header : header , data : data } ; enetframe } }